  // helper builders for translated value rows
  function sevLabel(sev) { return sev === 'high' ? L(T.sevHigh) : (sev === 'med' ? L(T.sevMed) : L(T.sevLow)); }
  function sevIcon(sev) { return sev === 'high' ? '🔴' : (sev === 'med' ? '🟡' : '🟢'); }
  function driveLabel(d) { return d === 'stop' ? L(T.driveStop) : (d === 'gentle' ? L(T.driveGently) : L(T.driveYes)); }

